node -e 'const fs=require("fs")
const fail=(m)=>{console.error("LIVE-2307: "+m);process.exit(1)}
const rd=(f)=>{try{return fs.readFileSync(f,"utf8")}catch(e){return ""}}
const t=rd("supabase/tests/analytics_experiment_runs.test.sql")
for(const d of ["a completed pilot can be re-run as a new run","a resumed pilot keeps its remaining enrollment days","guardrail review is recorded after follow-up","guardrail review is refused before the follow-up ends","a purge leaves a completed result unchanged"])if(!t.includes(d))fail("no pgTAP assertion: "+d)
const m=fs.readdirSync("supabase/migrations").filter((f)=>f.endsWith(".sql")).sort().map((f)=>rd("supabase/migrations/"+f).replace(/^\s*--.*$/gm," ")).join("\n")
const fn=(n)=>{const i=m.lastIndexOf("create or replace function public."+n+"(");if(i<0)fail("no "+n);return m.slice(i,m.indexOf("$$;",i))}
const fin=(fn("analytics_experiment_manage").match(/\x27finish\x27[\s\S]*?elsif/)||[""])[0]
if(!fin||/guardrails_reviewed_at/.test(fin))fail("finish still stamps the guardrail review, or has no branch")
if(!/\x27review_guardrails\x27/.test(fn("analytics_experiment_manage")))fail("no separate guardrail review command")
if(!/paused_for/.test(fn("analytics_experiment_assign")))fail("paused time still counts toward enrollment")
if(!/results_snapshot/.test(fn("analytics_experiment_results"))||!/results_snapshot/.test(fn("analytics_experiment_purge")))fail("a purge can still rewrite a completed result")
if(!rd("lib/analytics/rsvp-telemetry.schedule.test.ts"))fail("no unit test that the RSVP outcome is awaited within the request")'
